const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderSupplement(u){const s=supplements[u.id];return s?`<section class="teaching-notes"><h3>${esc(s.title)}</h3>${s.points.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="table-wrap"><table class="teaching-table"><caption>條件、做法與檢核</caption><thead><tr><th>辨識</th><th>做法</th><th>檢核</th></tr></thead><tbody>${s.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p><strong>自己試一次：</strong>${esc(s.task)}</p><details><summary>查看理由</summary><p>${esc(s.answer)}</p></details></section>`:'';}
